# Returns $Text translated to the active language (only PT-BR is currently supported besides
# English). Always call this wrapping any literal UI string shown to the user.
function T {
    param([string]$Text)
    if ($Script:CurrentLanguage -eq "PT" -and $Script:PT_BR.ContainsKey($Text)) { return $Script:PT_BR[$Text] }
    return $Text
}

# Reads the previously saved language code, falling back to "EN" if none/invalid.
function Get-GuiLanguagePref {
    $data = Get-GuiSettingsData
    if ($data["Language"] -eq "PT" -or $data["Language"] -eq "EN") { return $data["Language"] }
    return "EN"
}

# Persists the chosen language code so it's restored on the next launch.
function Save-GuiLanguagePref { param([string]$Lang) Save-GuiSettingValue -Key "Language" -Value $Lang }

# Sets the active language in memory and persists it. Does NOT re-render any page by itself -
# callers (e.g. the Settings page) are responsible for refreshing whatever is currently on screen.
function Set-GuiLanguage {
    param([Parameter(Mandatory)][string]$Lang)
    if ($Lang -ne "EN" -and $Lang -ne "PT") { return }
    $Script:CurrentLanguage = $Lang
    Save-GuiLanguagePref $Lang
}

# Initialized here (right after Get-GuiLanguagePref is defined, before Sidebar.ps1's
# Update-SidebarLanguage runs at load time) so Set-StrictMode -Version Latest does not throw
# "cannot be retrieved because it has not been set" on the very first T() call. Main\Startup.ps1
# re-reads the same preference later; this just guarantees a value exists beforehand.
# Falls back to "EN" when Get-GuiSettingsData (defined in Theme.ps1) is not loaded, as in test
# harnesses that source this file in isolation.
$Script:CurrentLanguage = if (Get-Command Get-GuiSettingsData -ErrorAction SilentlyContinue) { Get-GuiLanguagePref } else { "EN" }
#endregion
